{"function":"async () => {
// list tabbable sequence by simulating focus ordering is hard; instead gather deep focusables
const res=[];
function walk(root){ for(const el of root.querySelectorAll('*')){ if(el.shadowRoot) walk(el.shadowRoot); if(el.matches('a[href],button:not([disabled]),input,select,textarea,[tabindex]')) { if(el.offsetParent!==null || getComputedStyle(el).position==='fixed') res.push(el.tagName+(el.id?'#'+el.id:'')+'|'+(el.getAttribute('aria-label')??'')+'|'+el.textContent.trim().slice(0,30)+'|ti='+el.getAttribute('tabindex')); } } }
walk(document);
return res.slice(0,40);
}"}

